def SplitFeatureStyles():
    """CSS for smooth scroll-based fade-in animations (opt-in via SplitFeature_v1)."""
    return Style("""
        .fade-in-left {
            opacity: 0;
            transform: translateX(-30px);
            transition: opacity 0.8s ease-out, transform 0.8s ease-out;
        }
        
        .fade-in-right {
            opacity: 0;
            transform: translateX(30px);
            transition: opacity 0.8s ease-out, transform 0.8s ease-out;
        }
        
        .fade-in-left.visible,
        .fade-in-right.visible {
            opacity: 1;
            transform: translateX(0);
        }
    """)

def SplitFeatureScript():
    """JavaScript for scroll-triggered animations (opt-in via SplitFeature_v1)."""
    return Script("""
        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('visible');
                }
            });
        }, { threshold: 0.15, rootMargin: '0px 0px -50px 0px' });
        
        document.querySelectorAll('.fade-in-left, .fade-in-right').forEach(el => {
            observer.observe(el);
        });
    """)

