#| export
def SplitFeature(
    eyebrow: str,          # The small text above the headline
    title: str,            # The main headline
    description: str,      # The paragraph text
    image_src: str,        # URL for the image
    reverse: bool = False, # True = Image first, Text second
    animate: bool = False, # Animation is opt-in
    cls: str = "",
    style: str | None = None,  # Optional inline style (avoid by default)
    extra_css: str | None = None,  # Optional custom CSS (minimal; opt-in)
    extra_js: str | None = None,  # Optional custom JS (minimal; opt-in)
    block_cls: str = "",  # Additional classes for the inner wrapper
    text_cls: str = "",   # Extra classes for the text block
    image_cls: str = "",  # Extra classes for the image block
    ):
    """A split section (Text + Image) using BeerCSS (animation opt-in).
    
    Layout: two-column grid (roughly 60/40) using BeerCSS s/m/l spans.
    `reverse=True` swaps DOM order (image first).
    """
    hooks = []
    if animate:
        hooks.append(SplitFeatureStyles())
        hooks.append(SplitFeatureScript())
    if extra_css:
        hooks.append(Style(extra_css))
    if extra_js:
        hooks.append(Script(extra_js))
    
    text_anim = "fade-in-right" if (reverse and animate) else "fade-in-left" if animate else ""
    img_anim = "fade-in-left" if (reverse and animate) else "fade-in-right" if animate else ""
    
    text_block = SplitFeatureTextBlock(
        eyebrow=eyebrow,
        title=title,
        description=description,
        anim_cls=text_anim,
        cls=text_cls,
    )
    img_block = SplitFeatureImageBlock(
        image_src=image_src,
        alt=title,
        anim_cls=img_anim,
        cls=image_cls,
    )
    
    # 12-col: 7/5 ~= 58/42 (close to 60/40). Full-width stacking on small screens.
    text_cell = GridCell(text_block, span="s12 m7 l7")
    img_cell = GridCell(img_block, span="s12 m5 l5")
    content = [img_cell, text_cell] if reverse else [text_cell, img_cell]
    
    grid = ResponsiveGrid(*content, space="large-space", cls=f"middle-align {block_cls}".strip())
    # Default bottom margin prevents stacked SplitFeatures from visually overlapping/touching.
    return Section(
        *hooks,
        grid,
        cls=f"responsive large-padding bottom-margin {cls}".strip(),
        style=style,
    )

