def PricingSection(
    title: str,           # Section title
    monthly_price: str,   # Monthly price display
    yearly_price: str,    # Yearly price display
    plan_name: str,       # Name of the plan
    features: list,       # List of feature strings
    cta_text: str,        # CTA button text
    cta_href: str,        # CTA button href
    cls: str = "",        # Additional classes
    show_toggle: bool = False,  # When True, render HTMX toggle buttons
    monthly_url: str | None = None,  # HTMX endpoint for monthly pricing (opt-in)
    yearly_url: str | None = None,  # HTMX endpoint for yearly pricing (opt-in)
    price_target_id: str = "price-display",  # HTMX target element id
    style: str | None = None,  # Optional inline style (avoid by default)
    extra_css: str | None = None,  # Optional custom CSS (minimal; opt-in)
    extra_js: str | None = None,  # Optional custom JS (minimal; opt-in)
):
    """Pricing section (BeerCSS-first)."""
    hooks = []
    if extra_css:
        hooks.append(Style(extra_css))
    if extra_js:
        hooks.append(Script(extra_js))
    
    toggle_block = None
    if show_toggle and monthly_url and yearly_url:
        toggle_block = Div(
            Button(
                "Monthly",
                hx_get=monthly_url,
                hx_target=f"#{price_target_id}",
                hx_swap="innerHTML",
                variant="text",
            ),
            Button(
                "Yearly",
                hx_get=yearly_url,
                hx_target=f"#{price_target_id}",
                hx_swap="innerHTML",
                variant="text",
            ),
            cls="row middle-align center-align small-space",
        )
    
    feature_rows = [
        Li(
            Div(
                Icon("check", size="small"),
                Span(feature),
                cls="row middle-align small-space",
            )
        )
        for feature in features
    ]
    
    price_display = Div(id=price_target_id, cls="large-text bold")(
        Span(f"{monthly_price}/month"),
    )
    yearly_hint = P(f"{yearly_price}/year", cls="secondary-text") if yearly_price else None
    
    card = Card(
        H3(plan_name, cls="no-margin center-align"),
        Div(price_display, yearly_hint, cls="column center-align small-space"),
        Ul(*feature_rows, cls="column small-space"),
        Button(cta_text, href=cta_href, variant="raised"),
        cls="padding round",
    )
    
    return Section(
        *hooks,
        Div(
            H2(title, cls="center-align"),
            toggle_block,
            Div(card, cls="responsive"),
            cls="column center-align large-space",
        ),
        cls=f"large-padding {cls}".strip(),
        style=style,
    )

